	@Test
	public void testCloseAttemptsAllRetiredAndCurrentOwnersWhenOneCloseFails() throws Exception {
		SailSource source = mock(SailSource.class);
		SailDataset firstDataset = mock(SailDataset.class);
		SailDataset secondDataset = mock(SailDataset.class);
		SailDataset currentDataset = mock(SailDataset.class);
		SailSink firstSink = mock(SailSink.class);
		SailSink secondSink = mock(SailSink.class);
		SailSink currentSink = mock(SailSink.class);
		when(source.dataset(IsolationLevels.NONE)).thenReturn(firstDataset, secondDataset, currentDataset);
		when(source.sink(IsolationLevels.NONE)).thenReturn(firstSink, secondSink, currentSink);
		for (SailDataset dataset : List.of(firstDataset, secondDataset, currentDataset)) {
			when(dataset.getStatements(any(Resource.class), any(IRI.class), any(Value.class), any(Resource[].class)))
					.thenReturn(new EmptyIteration<>());
			when(dataset.prepareStatementCount(any(StatementCountScope.class))).thenReturn(StatementCountSources.EMPTY);
		}

		SailSourceModel model = new SailSourceModel(source);
		StatementCountScope firstScope = new StatementCountScope(null, null, null, new Resource[0]);
		StatementCountScope secondScope = new StatementCountScope(null, null, null, new Resource[0]);
		StatementCountScope currentScope = new StatementCountScope(null, null, null, new Resource[0]);
		model.snapshotForCounting(firstScope);
		model.add(RDF.TYPE, RDF.TYPE, RDF.TYPE);
		model.snapshotForCounting(secondScope);
		model.add(RDF.TYPE, RDF.TYPE, SimpleValueFactory.getInstance().createLiteral("second"));
		model.snapshotForCounting(currentScope);
		model.add(RDF.TYPE, RDF.TYPE, SimpleValueFactory.getInstance().createLiteral("current"));
		model.close();

		RuntimeException firstCloseFailure = new RuntimeException("first retired dataset close failed");
		RuntimeException secondCloseFailure = new RuntimeException("second retired dataset close failed");
		RuntimeException currentDatasetCloseFailure = new RuntimeException("current dataset close failed");
		RuntimeException currentSinkCloseFailure = new RuntimeException("current sink close failed");
		doThrow(firstCloseFailure).when(firstDataset).close();
		doThrow(secondCloseFailure).when(secondDataset).close();
		doThrow(currentDatasetCloseFailure).when(currentDataset).close();
		doThrow(currentSinkCloseFailure).when(currentSink).close();

		firstScope.close();
		secondScope.close();
		RuntimeException closeFailure = assertThrows(RuntimeException.class, currentScope::close);

		assertThat(closeFailure).isSameAs(firstCloseFailure);
		assertThat(closeFailure.getSuppressed()).containsExactly(secondCloseFailure, currentDatasetCloseFailure,
				currentSinkCloseFailure);
		verify(firstDataset).close();
		verify(secondDataset).close();
		verify(currentDataset).close();
		verify(currentSink).close();
	}

	@Test
	public void testDeferredOverflowClosePreservesFirstFailureAndCleansStore() {
		LmdbSailStore store = mock(LmdbSailStore.class);
		SailSource source = mock(SailSource.class);
		SailSink sink = mock(SailSink.class);
		when(store.getExplicitSailSource()).thenReturn(source);
		when(source.sink(IsolationLevels.NONE)).thenReturn(sink);
		AtomicReference<File> overflowDirectory = new AtomicReference<>();
		MemoryOverflowModel model = new MemoryOverflowModel() {
			@Override
			protected LmdbSailStore createSailStore(File dataDir) {
				overflowDirectory.set(dataDir);
				return store;
			}
		};
		model.overflowToDiskInner(new LinkedHashModel());
		assertThat(overflowDirectory.get()).isDirectory();
		StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0]);
		model.snapshotForCounting(scope);
		model.close();

		RuntimeException sinkFailure = new RuntimeException("overflow dataset sink close failed");
		RuntimeException storeFailure = new RuntimeException("overflow store close failed");
		doThrow(sinkFailure).when(sink).close();
		doThrow(storeFailure).when(store).close();

		RuntimeException closeFailure = assertThrows(RuntimeException.class, scope::close);

		assertThat(closeFailure).isSameAs(sinkFailure);
		assertThat(closeFailure.getSuppressed()).containsExactly(storeFailure);
		verify(sink).close();
		verify(store).close();
		assertThat(overflowDirectory.get()).doesNotExist();
	}

	@Test
	@Timeout(value = 15000, unit = MILLISECONDS)
	public void testCountingPendingWritesUsesReservedReaderWhenOrdinarySlotsAreFull(@TempDir File dataDir)
			throws Exception {
		LmdbSailStore store = new LmdbSailStore(dataDir, new StoreProperties(), new LmdbStoreConfig("spoc"));
		stores.add(store);
		storeDirs.add(dataDir);
		SailSourceModel model = new SailSourceModel(store);
		// add() checks the uncached statement first and keeps that root dataset's ordinary reader borrowed.
		model.add(RDF.TYPE, RDF.TYPE, SimpleValueFactory.getInstance().createLiteral("pending"));
		SailDataset cachedRoot = model.dataset;
		assertThat(cachedRoot).isNotNull();
		// The borrowed root uses one of 127 ordinary slots, leaving 126 for these additional readers.
		List<SailDataset> readers = new ArrayList<>(TxnManager.POOL_SIZE - 2);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<Integer> count = null;
		try {
			for (int i = 0; i < TxnManager.POOL_SIZE - 2; i++) {
				readers.add(store.getExplicitSailSource().dataset(IsolationLevels.NONE));
			}
			assertThat(readers).hasSize(TxnManager.POOL_SIZE - 2);
			count = executor.submit(model::size);
			assertThat(count.get(8, TimeUnit.SECONDS)).isEqualTo(1);
			assertThat(model.dataset).isNull();
		} catch (TimeoutException e) {
			throw new AssertionError(
					"Counting a pending native write must use the reserved reader while all ordinary readers are held",
					e);
		} finally {
			if (count != null && !count.isDone()) {
				count.cancel(true);
			}
			for (SailDataset reader : readers) {
				reader.close();
			}
			executor.shutdownNow();
			assertThat(executor.awaitTermination(3, TimeUnit.SECONDS)).isTrue();
			model.close();
		}
	}

	@Test
	@Timeout(value = 15000, unit = MILLISECONDS)
	public void testReadOnlyCountBorrowsCachedRootWhenOrdinarySlotsAreFull(@TempDir File dataDir) throws Exception {
		LmdbSailStore store = new LmdbSailStore(dataDir, new StoreProperties(), new LmdbStoreConfig("spoc"));
		stores.add(store);
		storeDirs.add(dataDir);
		try (SailSink sink = store.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			sink.approve(RDF.TYPE, RDF.TYPE, SimpleValueFactory.getInstance().createLiteral("committed"), null);
			sink.flush();
		}
		SailSourceModel model = new SailSourceModel(store);
		assertThat(model.contains(RDF.TYPE, RDF.TYPE, SimpleValueFactory.getInstance().createLiteral("committed")))
				.isTrue();
		SailDataset cachedRoot = model.dataset;
		assertThat(cachedRoot).isNotNull();
		List<SailDataset> readers = new ArrayList<>(TxnManager.POOL_SIZE - 2);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<List<Integer>> counts = null;
		try {
			for (int i = 0; i < TxnManager.POOL_SIZE - 2; i++) {
				readers.add(store.getExplicitSailSource().dataset(IsolationLevels.NONE));
			}
			assertThat(readers).hasSize(TxnManager.POOL_SIZE - 2);
			counts = executor.submit(() -> List.of(model.size(), model.size()));
			assertThat(counts.get(8, TimeUnit.SECONDS)).containsExactly(1, 1);
			assertThat(model.dataset).isSameAs(cachedRoot);
		} catch (TimeoutException e) {
			throw new AssertionError(
					"A cached model count must borrow its exact dataset when all ordinary readers are held", e);
		} finally {
			if (counts != null && !counts.isDone()) {
				counts.cancel(true);
			}
			for (SailDataset reader : readers) {
				reader.close();
			}
			executor.shutdownNow();
			assertThat(executor.awaitTermination(3, TimeUnit.SECONDS)).isTrue();
			model.close();
		}
	}

